@namespace sv_13fea46e9d0142e895021b89f55ff74b.Components.Pages.Board

<div class="task-card">
    <h4>@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge @GetPriorityClass()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="task-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move" @onclick="OnMoveLeftClicked">← Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move" @onclick="OnMoveRightClicked">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback OnMoveRight { get; set; }

    private string GetPriorityClass() => Task.Priority switch
    {
        "High" => "priority-high",
        "Medium" => "priority-medium",
        "Low" => "priority-low",
        _ => ""
    };

    private async System.Threading.Tasks.Task OnMoveLeftClicked() => await OnMoveLeft.InvokeAsync();
    private async System.Threading.Tasks.Task OnMoveRightClicked() => await OnMoveRight.InvokeAsync();
}

@namespace sv_13fea46e9d0142e895021b89f55ff74b.Components.Pages.Board

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="Save">Save</button>
        <button class="btn-cancel" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter]
    public EventCallback<NewTaskModel> OnSave { get; set; }

    [Parameter]
    public EventCallback OnCancel { get; set; }

    private string title = "";
    private string assignee = "";
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async System.Threading.Tasks.Task Save()
    {
        if (!string.IsNullOrWhiteSpace(title) && !string.IsNullOrWhiteSpace(assignee))
        {
            await OnSave.InvokeAsync(new NewTaskModel(title, assignee, priority, dueDate));
            ResetForm();
        }
    }

    private async System.Threading.Tasks.Task Cancel()
    {
        ResetForm();
        await OnCancel.InvokeAsync();
    }

    private void ResetForm()
    {
        title = "";
        assignee = "";
        priority = "Medium";
        dueDate = DateTime.Today.AddDays(7);
    }

    public record NewTaskModel(string Title, string Assignee, string Priority, DateTime DueDate);
}

@namespace sv_13fea46e9d0142e895021b89f55ff74b.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="() => MoveLeft(task)"
                      OnMoveRight="() => MoveRight(task)" />
        }
    </div>
    <div class="column-footer">
        @if (showAddForm)
        {
            <AddTaskForm OnSave="HandleSave" OnCancel="() => showAddForm = false" />
        }
        else
        {
            <button class="btn-add-task" @onclick="() => showAddForm = true">+ Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string Title { get; set; } = "";

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveRight { get; set; }

    [Parameter]
    public EventCallback<AddTaskForm.NewTaskModel> OnAddTask { get; set; }

    private bool showAddForm;

    private async System.Threading.Tasks.Task MoveLeft(TaskItem task) => await OnMoveLeft.InvokeAsync(task);
    private async System.Threading.Tasks.Task MoveRight(TaskItem task) => await OnMoveRight.InvokeAsync(task);

    private async System.Threading.Tasks.Task HandleSave(AddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync(model);
        showAddForm = false;
    }
}

@namespace sv_13fea46e9d0142e895021b89f55ff74b.Components.Pages.Board

<div class="board-stats-bar">
    <span class="stat">Total: @Tasks.Count</span>
    <span class="stat">To Do: @Tasks.Count(t => t.Status == "To Do")</span>
    <span class="stat">In Progress: @Tasks.Count(t => t.Status == "In Progress")</span>
    <span class="stat">Done: @Tasks.Count(t => t.Status == "Done")</span>
    <span class="stat stat-overdue">Overdue: @Tasks.Count(t => t.DueDate < DateTime.Today)</span>
</div>

@code {
    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();
}

@namespace sv_13fea46e9d0142e895021b89f55ff74b.Components.Pages.Board

<div class="board-search-bar">
    <input type="text" placeholder="Search tasks by title..." value="@SearchText"
           @oninput="OnInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = "";

    [Parameter]
    public EventCallback<string> SearchTextChanged { get; set; }

    private async System.Threading.Tasks.Task OnInput(ChangeEventArgs e)
    {
        await SearchTextChanged.InvokeAsync(e.Value?.ToString() ?? "");
    }
}

