}

.column-header h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1rem;
    color: #495057;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 100px;
}

.column-footer {
    margin-top: 0.75rem;
}

